//! The truth's source-map decoder (experiments/096 `decoder.py`, scorer 6):
//! generated byte offset -> (source, original line, original column).
//!
//! Two corrections over scorer 4's decoder, each switchable so that both
//! off reproduces it exactly:
//!
//! - `utf16`: a generated column counts UTF-16 code units (the v3 spec),
//!   not code points. A column that splits a surrogate pair is read the
//!   way Python's `surrogatepass` codec reads it: each half is three UTF-8
//!   bytes.
//! - `unmapped`: a one-field segment means "maps to no source" and is kept
//!   as `src = None`; through a composed map a position the inner map does
//!   not cover (or covers with a one-field segment) is `None` too.

/// One decoded mapping: (generated column, source, original line, column);
/// the last three are None for a one-field segment.
pub type Mapping = (i64, Option<i64>, Option<i64>, Option<i64>);

/// One truth segment: (generated byte offset, source, line, column).
pub type Segment = (i64, Option<i64>, Option<i64>, Option<i64>);

fn b64(c: u8) -> Result<i64, String> {
    let v = match c {
        b'A'..=b'Z' => c - b'A',
        b'a'..=b'z' => c - b'a' + 26,
        b'0'..=b'9' => c - b'0' + 52,
        b'+' => 62,
        b'/' => 63,
        _ => return Err(format!("bad base64 character {:?} in mappings", c as char)),
    };
    Ok(i64::from(v))
}

/// The VLQ fields of one segment.
pub fn vlq(seg: &str) -> Result<Vec<i64>, String> {
    let mut out = Vec::new();
    let (mut val, mut shift) = (0i64, 0u32);
    for c in seg.bytes() {
        let d = b64(c)?;
        val += (d & 31) << shift;
        if d & 32 != 0 {
            shift += 5;
        } else {
            out.push(if val & 1 != 0 { -(val >> 1) } else { val >> 1 });
            val = 0;
            shift = 0;
        }
    }
    Ok(out)
}

/// Per generated line, its mappings; a one-field segment is kept as
/// `(col, None, None, None)` when `unmapped`, else dropped.
pub fn decode(mappings: &str, unmapped: bool) -> Result<Vec<Vec<Mapping>>, String> {
    let mut out = Vec::new();
    let (mut src, mut ol, mut oc) = (0i64, 0i64, 0i64);
    for group in mappings.split(';') {
        let mut col = 0i64;
        let mut row = Vec::new();
        for seg in group.split(',').filter(|s| !s.is_empty()) {
            let v = vlq(seg)?;
            col += v.first().copied().unwrap_or(0);
            if v.len() >= 4 {
                src += v[1];
                ol += v[2];
                oc += v[3];
                row.push((col, Some(src), Some(ol), Some(oc)));
            } else if unmapped {
                row.push((col, None, None, None));
            }
        }
        out.push(row);
    }
    Ok(out)
}

/// Python's slice bounds `[a:b]` over a sequence of `len` items.
fn py_bounds(len: usize, a: i64, b: i64) -> (usize, usize) {
    let fix = |i: i64| -> usize {
        let len = len as i64;
        let i = if i < 0 { i + len } else { i };
        i.clamp(0, len) as usize
    };
    let (a, b) = (fix(a), fix(b));
    (a, b.max(a))
}

/// UTF-8 bytes of a UTF-16 code-unit run decoded with `surrogatepass`.
fn utf8_len_u16(units: &[u16]) -> usize {
    let mut n = 0;
    let mut k = 0;
    while k < units.len() {
        let u = units[k];
        if (0xD800..0xDC00).contains(&u)
            && units
                .get(k + 1)
                .is_some_and(|l| (0xDC00..0xE000).contains(l))
        {
            n += 4;
            k += 2;
            continue;
        }
        n += match u {
            0..=0x7F => 1,
            0x80..=0x7FF => 2,
            _ => 3,
        };
        k += 1;
    }
    n
}

/// Generated column -> byte offset within one line, walked forward
/// (decoder.py `_Line`: a step back restarts from the line start).
struct Line {
    ascii: bool,
    utf16: bool,
    units: Vec<u16>,
    chars: Vec<char>,
    pc: i64,
    pb: usize,
}

impl Line {
    fn new(line: &str, utf16: bool) -> Line {
        let ascii = line.is_ascii();
        Line {
            ascii,
            utf16,
            units: if utf16 && !ascii {
                line.encode_utf16().collect()
            } else {
                Vec::new()
            },
            chars: if !utf16 && !ascii {
                line.chars().collect()
            } else {
                Vec::new()
            },
            pc: 0,
            pb: 0,
        }
    }

    fn byte(&mut self, col: i64) -> i64 {
        if self.ascii {
            return col;
        }
        if col < self.pc {
            self.pc = 0;
            self.pb = 0;
        }
        self.pb += if self.utf16 {
            let (a, b) = py_bounds(self.units.len(), self.pc, col);
            utf8_len_u16(&self.units[a..b])
        } else {
            let (a, b) = py_bounds(self.chars.len(), self.pc, col);
            self.chars[a..b].iter().map(|c| c.len_utf8()).sum()
        };
        self.pc = col;
        self.pb as i64
    }
}

/// A composed (inner) map: its decoded lines and its line offset.
pub struct Inner {
    pub lines: Vec<Vec<Mapping>>,
    pub offset: i64,
}

/// decoder.py `segments`: every mapping as a byte-offset segment, in
/// generated order, through `inner` when given.
pub fn segments(
    text: &str,
    mappings: &str,
    inner: Option<&Inner>,
    utf16: bool,
    unmapped: bool,
) -> Result<Vec<Segment>, String> {
    let lines: Vec<&str> = text.split('\n').collect();
    let rows = decode(mappings, unmapped)?;
    let mut icols: std::collections::HashMap<usize, Vec<i64>> = std::collections::HashMap::new();
    let mut out = Vec::new();
    let mut start = 0i64;
    for (li, row) in rows.iter().enumerate() {
        let line = lines.get(li).copied().unwrap_or("");
        let mut at = Line::new(line, utf16);
        for &(col, src, ol, oc) in row {
            let off = start + at.byte(col);
            let (Some(inner), Some(_)) = (inner, src) else {
                out.push((off, src, ol, oc));
                continue;
            };
            let il = ol.expect("a mapped segment has a line") - inner.offset;
            let ilines = &inner.lines;
            if il < 0 || il as usize >= ilines.len() || ilines[il as usize].is_empty() {
                if unmapped {
                    out.push((off, None, None, None));
                }
                continue;
            }
            let il = il as usize;
            let cols = icols
                .entry(il)
                .or_insert_with(|| ilines[il].iter().map(|x| x.0).collect());
            let oc = oc.expect("a mapped segment has a column");
            let k = cols.partition_point(|&c| c <= oc).saturating_sub(1);
            let hit = ilines[il][k];
            if hit.1.is_none() {
                out.push((off, None, None, None));
                continue;
            }
            out.push((off, hit.1, hit.2, hit.3));
        }
        start += line.len() as i64 + 1;
    }
    Ok(out)
}

